        "func": "//var port = msg.port;\n//msg.topic = \"lora/send/\" + port;\n\nlet message = {};\n\nvar port = msg.port;\nmessage.topic = \"lora/send/\" + port;\n\nif (Array.isArray(msg.payload)) {\n    // Convert array of numbers/bytes into a Buffer\n    message.payload = Buffer.from(msg.payload);\n}else{\n    message.payload=msg.payload;\n}\n\nreturn message;\n\n\n//if( typeof msg.payload  == msg.payload )\n    //msg.payload = JSON.stringify( msg.payload );\n//msg.input = msg.payload;\nreturn msg;",
