        "g": "2678be316e5d216b",
        "name": "Set frequency timer (5-60 min)(0x0500-0x3C00)",
        "func": "const dbgMode = flow.get(\"dbgMode\");\nvar minutes =300;\nvar message={};\nvar minutes = parseInt(msg.payload.array[0]);\n/*if (isAsciiString(msg.payload.array[0])===true){\n    minutes = msg.payload.array[0].charCodeAt();\n}else{    \n    minutes = parseInt(msg.payload.array[0]);\n}*/\n\nif (dbgMode) node.warn(minutes);\nif( minutes <= 0 ) minutes = 5;\nif (minutes > 60) minutes = 60;\n\nmessage.payload = minutes * 60;\nflow.set(\"timerSeconds\", message.payload );\n\nreturn message;\n\nfunction isAsciiString(data) {\nvar isAscii = true;\nvar temp = parseInt(data);\n    if (temp.isNaN){ isAscii=false}else{isAscii=true}\nreturn isAscii;\n    \n    /*\n        if (text.charCodeAt(0) > 127)\n            return false;\n    return true;*/\n/*    let isAscii = true;\n    if (text && !text.match(/^[\\x00-\\x7F]+$/g)) {\n        isAscii = false;\n    }\n    return isAscii;*/\n}\n",
        "outputs": 1,
