        "type": "function",
        "z": "1989165f1d1369c8",
        "g": "4d6f178df94b54a8",
        "name": "timerSeconds frequency",
        "func": "var now = new Date().getTime();\nvar lastPublish = flow.get(\"lastPublish\");\nif(!lastPublish)\n    now;\n\nvar timerSeconds = flow.get(\"timerSeconds\") || 300;  //Set 5 minutes as default;\n\nif( now - lastPublish < (timerSeconds * 1000) )\n    return;\n \nflow.set(\"lastPublish\", now);\nlet dtNow = new Date().toLocaleString(\"sv-SE\", { timeZone: \"Europe/Stockholm\" })\nnode.status({fill:\"green\",shape:\"dot\",text: \"Senast trig\"+dtNow});\nreturn msg;\n\n",
