        "func": "var message={};\nmessage.port = parseInt(msg.topic.replace(\"lora/receive/\",\"\"));\nmessage.topic=msg.topic;\nvar hexArray = msg.payload;\n\n\nvar buf = \"\"\nfor (var i=0;i<hexArray.length;i++){\n    buf += hexArray[i].toString(16).padStart(2, '0').toUpperCase();\n}\n\nmessage.payload={\n    \"array\":hexArray,\n    \"datastring\":buf\n}\nreturn message;",
