        "g": "9f01ce414b45145b",
        "name": "No of unconf",
        "func": "const dbgMode = flow.get(\"dbgMode\");\n\nvar unconfCNT = flow.get(\"unconfCNT\")||1;\nunconfCNT += 1;\n\nif (Buffer.isBuffer(msg.payload)){\n    if (dbgMode) node.warn(\"Buffered payload\");\n} else { if (dbgMode) node.warn(\"Not buffered payload\"); }\n\nif (unconfCNT===10){\n    msg.topic = msg.topic+\"/c\";\n    flow.set(\"unconfCNT\",0);\n    return [msg,msg];\n}\nflow.set(\"unconfCNT\",unconfCNT);\nreturn [msg,null];",
