        "func": "const dbgMode = flow.get(\"dbgMode\");\n\n\nvar message={};\n\nif(msg.payload.hasOwnProperty(\"ip\")){\n  if (dbgMode) node.warn(\"ip request2transmit\");\n  var buf = (verifyIP4(msg.payload.ip));\n  message.payload=buf;\n  message.port=10;\n  return message;\n} else if (msg.payload.hasOwnProperty(\"Status\")) {\n    if (msg.payload.Status === 19){\n      if (dbgMode) node.warn(\"LoRaWAN settings updated\");\n      var bufnr = [];\n      bufnr.push(19);\n      bufnr.push(0x01);\n      message.payload = bufnr;\n      message.port = 10;\n      return message;\n    } else if (msg.payload.Status === 3) {\n      if (dbgMode) node.warn(\"LoRaWAN message too large\");\n      var largeMsg = flow.get(\"largeMsg\")||1;\n      if (largeMsg != 1){\n        if (msg.payload.Length >= largeMsg.MsgLength){\n          flow.set(\"largeMsg\", 1);\n          let macDiff = largeMsg.MsgLength - msg.payload.Length;\n          sendLargeMsg(msg.payload.MaxLength-macDiff, largeMsg);\n        }\n\n      }\n      return;\n    }\n}\nreturn;\n\n\n\nfunction verifyIP4(address) {\nvar bufferts = [];\nvar ip = address;\nvar parts= ip.split(/[.:]/);\n  if (parts.length === 4) {\n\n    // Check IPv4 parts\n    for (const part of parts) {\n      const num = parseInt(part, 10);\n      bufferts.push(num);\n    }\n    return bufferts;\n}\n}\n\nfunction encodeBase64 (data){\n return Buffer.from(data).toString('base64');\n}\n\nfunction sendLargeMsg(AllowedPkgSize, largeMsg) {\n  //Om SF12\n  //Max MAC = 3 Bytes => Max Data 48 Bytes\n  //3 Bytes För bryta upp paket => 45 Bytes\n  var largeMessage = {};\n  var hexBuff = [];\n\n  //const AllowedPkgSize = 45;\n  var CNT = flow.get(\"CNTNo\") || 1;\n  var buf = \"\";\n  var numb = 0;\n  //var splitData = [];\n  AllowedPkgSize = AllowedPkgSize - 6; //6 extra Bytes added\n  var NoOfPkg = Math.round(largeMsg.Message.length / AllowedPkgSize);\n  //var portNo = parseInt(largeMsg.Topic.replace(\"lora/send/\",\"\"));\n  var portNoString = largeMsg.Topic.replace(\"lora/send/\", \"\");\n  var portNo = parseInt(portNoString);\n  //if (dbgMode) node.warn(\"portNo: \"+ portNo);\n  //if (dbgMode) node.warn(\"NoOfPkg: \" + NoOfPkg);\n  for (var i = 0; i < NoOfPkg + 1; i++) {\n    //node.warn(\"NoOfPkgLeftAdj: \" + ((NoOfPkg + 1) << 4));\n    //node.warn(\"NoOfPkg: \" + (((NoOfPkg + 1) << 4) & 0xF0));\n    //node.warn(\"package No: \" + (i + 1));\n    buf += portNo.toString(16).padStart(2, '0').toUpperCase();\n\n    numb = ((((NoOfPkg + 1) << 4) & 0xF0));\n    node.warn(numb);\n    numb = numb + ((i + 1) & 0x0F)\n    //if (dbgMode) node.warn(numb);\n    buf += numb;\n    buf += CNT;\n    //output = Buffer.from(input, 'hex');\n    node.warn(buf);\n    buf += Buffer.from(largeMsg.Message.slice((i * AllowedPkgSize), ((i + 1) * AllowedPkgSize)),'hex');\n    largeMessage.payload = buf; //hexStringToArrayBuffer(hexBuff);\n    buf = \"\";\n    largeMessage.port = 30;\n    node.warn(largeMessage);\n  }\n  CNT += 1;\n  flow.set(\"CNTNo\", CNT);\n  return;\n}\n/*\nfunction sendLargeMsgOld(AllowedPkgSize, largeMsg ){\n  //Om SF12\n  //Max MAC = 3 Bytes => Max Data 48 Bytes\n  //3 Bytes För bryta upp paket => 45 Bytes\n  var largeMessage={};\n\n  //const AllowedPkgSize = 45;\n  var CNT = flow.get(\"CNTNo\") || 1;\n  var buf = \"\";\n  var numb = 0;\n  //var splitData = [];\n  AllowedPkgSize = AllowedPkgSize-6; //6 extra Bytes added\n  var NoOfPkg = Math.round(largeMsg.Message.length / AllowedPkgSize);\n  //var portNo = parseInt(largeMsg.Topic.replace(\"lora/send/\",\"\"));\n  var portNoString = largeMsg.Topic.replace(\"lora/send/\",\"\");\n  var portNo = parseInt(portNoString);\n  //if (dbgMode) node.warn(\"portNo: \"+ portNo);\n  //if (dbgMode) node.warn(\"NoOfPkg: \" + NoOfPkg);\n  for (var i = 0; i < NoOfPkg + 1; i++) {\n    //node.warn(\"NoOfPkgLeftAdj: \" + ((NoOfPkg + 1) << 4));\n    //node.warn(\"NoOfPkg: \" + (((NoOfPkg + 1) << 4) & 0xF0));\n    //node.warn(\"package No: \" + (i + 1));\n    buf += portNo.toString(16).padStart(2, '0').toUpperCase();\n\n    numb = ((((NoOfPkg + 1) << 4) & 0xF0));\n    node.warn(numb);\n    numb = numb + ((i + 1) & 0x0F)\n    //if (dbgMode) node.warn(numb);\n    buf += numb.toString(16).padStart(2, '0').toUpperCase();\n    buf += CNT.toString(16).padStart(2, '0').toUpperCase();\n\n    largeMessage.payload=(buf + largeMsg.Message.slice((i * AllowedPkgSize), ((i + 1) * AllowedPkgSize)));\n    buf = \"\";\n    largeMessage.port =30;\n    node.send(largeMessage);\n  }\n  CNT += 1;\n  flow.set(\"CNTNo\", CNT);\nreturn;\n}*/\n\n/**\n * Convert a hex string to an ArrayBuffer.\n * \n * @param {string} hexString - hex representation of bytes\n * @return {ArrayBuffer} - The bytes in an ArrayBuffer.\n */\nfunction hexStringToArrayBuffer(hexString) {\n    // remove the leading 0x\n    hexString = hexString.replace(/^0x/, '');\n    \n    // ensure even number of characters\n    if (hexString.length % 2 != 0) {\n        node.warn('WARNING: expecting an even number of characters in the hexString');\n    }\n    \n    // check for some non-hex characters\n    var bad = hexString.match(/[G-Z\\s]/i);\n    if (bad) {\n        node.warn('WARNING: found non-hex characters: '+ bad);    \n    }\n    \n    // split the string into pairs of octets\n    var pairs = hexString.match(/[\\dA-F]{2}/gi);\n    \n    // convert the octets to integers\n    var integers = pairs.map(function(s) {\n        return parseInt(s, 16);\n    });\n    \n    var array = new Uint8Array(integers);\n    console.log(array);\n    \n    return array.buffer;\n}",
